create table if not exists public.conversations (id uuid primary key default gen_random_uuid(),buyer_id uuid not null references auth.users(id) on delete cascade,seller_id uuid not null references auth.users(id) on delete cascade,listing_id uuid references public.listings(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint conversations_different_users check (buyer_id<>seller_id));
create unique index if not exists conversations_unique_participants_listing on public.conversations(buyer_id,seller_id,coalesce(listing_id,'00000000-0000-0000-0000-000000000000'::uuid));
create index if not exists conversations_buyer_id_idx on public.conversations(buyer_id);create index if not exists conversations_seller_id_idx on public.conversations(seller_id);
create table if not exists public.messages (id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,body text not null check(char_length(trim(body)) between 1 and 2000),created_at timestamptz not null default now(),read_at timestamptz);
create index if not exists messages_conversation_created_idx on public.messages(conversation_id,created_at);alter table public.conversations enable row level security;alter table public.messages enable row level security;
drop policy if exists "Participants can view conversations" on public.conversations;create policy "Participants can view conversations" on public.conversations for select to authenticated using(auth.uid()=buyer_id or auth.uid()=seller_id);
drop policy if exists "Users can start conversations" on public.conversations;create policy "Users can start conversations" on public.conversations for insert to authenticated with check(auth.uid()=buyer_id and buyer_id<>seller_id);
drop policy if exists "Participants can view messages" on public.messages;create policy "Participants can view messages" on public.messages for select to authenticated using(exists(select 1 from public.conversations where conversations.id=messages.conversation_id and(conversations.buyer_id=auth.uid() or conversations.seller_id=auth.uid())));
drop policy if exists "Participants can send messages" on public.messages;create policy "Participants can send messages" on public.messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.conversations where conversations.id=messages.conversation_id and(conversations.buyer_id=auth.uid() or conversations.seller_id=auth.uid())));
grant select,insert on public.conversations to authenticated;grant select,insert on public.messages to authenticated;
create or replace function public.update_conversation_after_message() returns trigger language plpgsql security definer set search_path='' as $$ begin update public.conversations set updated_at=new.created_at where id=new.conversation_id;return new;end;$$;
drop trigger if exists update_conversation_timestamp on public.messages;create trigger update_conversation_timestamp after insert on public.messages for each row execute function public.update_conversation_after_message();
